selector_to_html = {"a[href=\"#pyskyfire.ducts.port.ResolvedPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResolvedPort</span></span></dt><dd><p>A duct placed in machine coordinates.</p></dd>", "a[href=\"#pyskyfire.ducts.port.ResolvedPort.sweep\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort.sweep\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">64</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">9</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The duct\u2019s own wall, as closed boundary rings [m, shape (N, M, 3)].</p><p>The duct\u2019s own frame, not the passage\u2019s: a stub leaves along the way its\nsection faces, so that section\u2019s outward direction <em>is</em> the duct axis\nand spanning the cross-section with it would flatten the tube into the\nplane it should be normal to.</p></dd>", "a[href=\"#pyskyfire.ducts.port.ResolvedPort.is_straight\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort.is_straight\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">is_straight</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.port.ResolvedPort._start_frame\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort._start_frame\">\n<span class=\"sig-name descname\"><span class=\"pre\">_start_frame</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>A frame spanning the plane the duct starts in.</p><p>Radial is taken from where the outlet sits rather than from the\ndirection it leaves along, so a clockwise volute \u2013 whose tangential\nruns the other way \u2013 still gets radial pointing outward. Where the\nduct leaves along a direction radial is not perpendicular to, as a\nmanifold\u2019s does, radial is squared up against it first.</p></dd>", "a[href=\"#pyskyfire.ducts.port.ResolvedPort._axis\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort._axis\">\n<span class=\"sig-name descname\"><span class=\"pre\">_axis</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire-ducts-port-resolvedport\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.port.ResolvedPort<a class=\"headerlink\" href=\"#pyskyfire-ducts-port-resolvedport\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.port.ResolvedPort.frames\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedPort.frames\">\n<span class=\"sig-name descname\"><span class=\"pre\">frames</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">17</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">start_frame</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Centreline points and a non-twisting cross-section frame.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
